// Platform primitive: Evidence with immutability guarantees

export type EvidenceStatus = 'raw' | 'validated' | 'disputed' | 'superseded';
export type EvidenceSource = 'sensor' | 'api' | 'human' | 'derived' | 'inference';

export interface EvidenceMetadata {
  capturedAt: string;           // ISO 8601 — immutable once set
  capturedBy: string;           // agent or user ID
  source: EvidenceSource;
  confidence: number;           // 0–1
  tags: string[];
}

export interface Evidence<T = unknown> {
  id: string;                   // UUID, immutable
  domainType: string;           // e.g. 'flight.disruption', 'sentiment.signal'
  payload: T;                   // domain-specific data
  metadata: EvidenceMetadata;
  hash: string;                 // SHA-256 of payload+metadata for tamper detection
  supersededBy?: string;        // ID of replacement evidence (if updated)
}

export interface EvidenceStore<T = unknown> {
  append(evidence: Evidence<T>): Promise<void>;
  getById(id: string): Promise<Evidence<T> | null>;
  getByDomain(domainType: string, since?: string): Promise<Evidence<T>[]>;
  getChain(id: string): Promise<Evidence<T>[]>;  // follows supersededBy chain
}

