// Platform primitive: Hypothesis with full version history

export type HypothesisStatus = 'proposed' | 'testing' | 'supported' | 'refuted' | 'archived';
export type HypothesisConfidence = 'low' | 'medium' | 'high' | 'confirmed';

export interface HypothesisVersion {
  version: number;              // monotonically increasing
  content: string;              // the hypothesis statement
  rationale: string;            // why this version was created
  evidenceIds: string[];        // evidence supporting this version
  confidence: HypothesisConfidence;
  status: HypothesisStatus;
  createdAt: string;            // ISO 8601
  createdBy: string;            // agent or user ID
}

export interface Hypothesis {
  id: string;                   // UUID, immutable
  domainType: string;           // e.g. 'crew.fatigue', 'sentiment.trend'
  currentVersion: number;       // pointer to latest HypothesisVersion
  versions: HypothesisVersion[];
  tags: string[];
  createdAt: string;            // ISO 8601 — immutable
  updatedAt: string;            // ISO 8601 — updated on each new version
}

export interface HypothesisStore {
  create(hypothesis: Omit<Hypothesis, 'id' | 'createdAt' | 'updatedAt'>): Promise<Hypothesis>;
  addVersion(id: string, version: Omit<HypothesisVersion, 'version' | 'createdAt'>): Promise<Hypothesis>;
  getById(id: string): Promise<Hypothesis | null>;
  getByDomain(domainType: string): Promise<Hypothesis[]>;
  getVersion(id: string, version: number): Promise<HypothesisVersion | null>;
}

