// Platform primitive: Intent — structured goal representation

export type IntentPriority = 'low' | 'medium' | 'high' | 'critical';
export type IntentStatus = 'active' | 'paused' | 'completed' | 'cancelled';

export interface IntentConstraint {
  type: string;                 // e.g. 'time_window', 'resource_limit', 'regulatory'
  value: unknown;
  hard: boolean;                // hard = must not violate; soft = prefer not to
}

export interface Intent {
  id: string;                   // UUID, immutable
  domainType: string;           // e.g. 'crew.scheduling', 'sentiment.analysis'
  goal: string;                 // natural language goal statement
  priority: IntentPriority;
  constraints: IntentConstraint[];
  status: IntentStatus;
  evidenceIds: string[];        // evidence informing this intent
  hypothesisIds: string[];      // hypotheses relevant to this intent
  createdAt: string;            // ISO 8601
  updatedAt: string;
  resolvedAt?: string;
  resolution?: string;          // outcome description
}

export interface IntentStore {
  create(intent: Omit<Intent, 'id' | 'createdAt' | 'updatedAt'>): Promise<Intent>;
  update(id: string, patch: Partial<Pick<Intent, 'status' | 'priority' | 'resolution' | 'resolvedAt' | 'evidenceIds' | 'hypothesisIds'>>): Promise<Intent>;
  getById(id: string): Promise<Intent | null>;
  getActive(domainType?: string): Promise<Intent[]>;
  resolve(id: string, resolution: string): Promise<Intent>;
}

