// Platform primitive: Knowledge Graph persistence

export type NodeType = 'entity' | 'concept' | 'event' | 'pattern' | 'agent';
export type EdgeType = 'relates_to' | 'causes' | 'supports' | 'contradicts' | 'precedes' | 'contains';

export interface KGNode {
  id: string;                   // UUID, immutable
  type: NodeType;
  label: string;
  properties: Record<string, unknown>;
  domainType: string;           // e.g. 'crew', 'sentiment'
  createdAt: string;
  updatedAt: string;
}

export interface KGEdge {
  id: string;                   // UUID, immutable
  fromNodeId: string;
  toNodeId: string;
  type: EdgeType;
  weight: number;               // 0–1 relationship strength
  properties: Record<string, unknown>;
  evidenceIds: string[];        // evidence supporting this edge
  createdAt: string;
}

export interface KGQuery {
  nodeTypes?: NodeType[];
  edgeTypes?: EdgeType[];
  domainType?: string;
  labels?: string[];
  since?: string;               // ISO 8601
  limit?: number;
}

export interface KnowledgeGraphStore {
  addNode(node: Omit<KGNode, 'id' | 'createdAt' | 'updatedAt'>): Promise<KGNode>;
  addEdge(edge: Omit<KGEdge, 'id' | 'createdAt'>): Promise<KGEdge>;
  getNode(id: string): Promise<KGNode | null>;
  getNeighbours(nodeId: string, edgeTypes?: EdgeType[]): Promise<{ node: KGNode; edge: KGEdge }[]>;
  query(q: KGQuery): Promise<{ nodes: KGNode[]; edges: KGEdge[] }>;
  updateNode(id: string, properties: Record<string, unknown>): Promise<KGNode>;
}

