// Platform primitive: Pattern with maturity lifecycle

export type PatternMaturity = 'emerging' | 'candidate' | 'established' | 'deprecated';
export type PatternCategory = 'operational' | 'behavioural' | 'temporal' | 'causal' | 'predictive';

export interface PatternOccurrence {
  evidenceId: string;
  observedAt: string;           // ISO 8601
  context: Record<string, unknown>;
}

export interface Pattern {
  id: string;                   // UUID, immutable
  domainType: string;           // e.g. 'crew.fatigue', 'sentiment.volatility'
  name: string;
  description: string;
  category: PatternCategory;
  maturity: PatternMaturity;
  occurrences: PatternOccurrence[];
  occurrenceCount: number;      // denormalised for fast queries
  firstObservedAt: string;      // ISO 8601
  lastObservedAt: string;       // ISO 8601
  promotionThreshold: number;   // occurrences needed to advance maturity
  tags: string[];
}

export interface PatternStore {
  upsert(pattern: Omit<Pattern, 'id' | 'firstObservedAt' | 'lastObservedAt'>): Promise<Pattern>;
  recordOccurrence(id: string, occurrence: PatternOccurrence): Promise<Pattern>;
  promote(id: string): Promise<Pattern>;                // advances maturity
  getByDomain(domainType: string): Promise<Pattern[]>;
  getByMaturity(maturity: PatternMaturity): Promise<Pattern[]>;
}

