// Platform primitive: Workspace — isolated reasoning context per session/agent

export type WorkspaceStatus = 'active' | 'suspended' | 'archived';

export interface WorkspaceSnapshot {
  snapshotId: string;
  takenAt: string;              // ISO 8601
  evidenceIds: string[];
  hypothesisIds: string[];
  intentIds: string[];
  patternIds: string[];
  notes: string;
}

export interface Workspace {
  id: string;                   // UUID, immutable
  domainType: string;
  ownerId: string;              // agent or user ID
  status: WorkspaceStatus;
  evidenceIds: string[];
  hypothesisIds: string[];
  intentIds: string[];
  patternIds: string[];
  snapshots: WorkspaceSnapshot[];
  createdAt: string;
  updatedAt: string;
}

export interface WorkspaceStore {
  create(workspace: Omit<Workspace, 'id' | 'createdAt' | 'updatedAt' | 'snapshots'>): Promise<Workspace>;
  addEvidence(id: string, evidenceId: string): Promise<Workspace>;
  addHypothesis(id: string, hypothesisId: string): Promise<Workspace>;
  addIntent(id: string, intentId: string): Promise<Workspace>;
  addPattern(id: string, patternId: string): Promise<Workspace>;
  snapshot(id: string, notes: string): Promise<WorkspaceSnapshot>;
  getById(id: string): Promise<Workspace | null>;
  archive(id: string): Promise<Workspace>;
}

